// From "correction sheets" (1WOErvuYawblG-HkrK5In5YWtEiKKt_DeoVpmL5na6GU), read 2026-09-07.
// Only fields the sheet actually specifies are written. 'same as previous' -> left untouched.
const EDITS = [
  { investor: 'Fireside Ventures',    contact_person: 'Sonia', email: 'sonia@firesideventures.com' },
  { investor: 'PiperSireca',          contact_person: 'Amit Ghule' },
  { investor: 'Riceberg Ventures',    contact_person: 'Abhinav Gupta', sector: 'Foundational AI technology' },
  { investor: 'Siana Capital',        contact_person: 'Rajat Shah', sector: 'B2B deep-tech business models' },
  { investor: '247 VC Tech Fund',     contact_person: 'Kruti', sector: 'Deep tech' },
  { investor: 'Swishin Ventures',     contact_person: 'Falak Mohnot', email: 'falak@swishin.vc', sector: 'Sector agnostic (Tier 2 & Tier 3 India)', stage: 'Pre-Seed to Seed' },
  { investor: 'Atomic Capital',       contact_person: 'Nikhil Patil', sector: 'Consumer / Consumer Tech / Consumer enabler' },
  { investor: 'CedarHill Capital',    contact_person: 'Subit, Hriday', email: 'subit@cedarhill.vc,Hriday@cedarhill.vc', sector: 'Enterprise tech for BFSI' },
  { investor: 'Rainmatter by Zerodha', contact_person: 'Nihal Shetty', sector: 'HealthTech, ClimateTech, DeepTech, FinTech' },
  { investor: 'Zeren Capital',        contact_person: 'Sidhi Dalmia', stage: 'Pre-Series A to Series C', cheque_inr_cr: 'INR 10 Cr minimum' }
];

function s(v) { return String(v == null ? '' : v).trim(); }
const rows = $input.all().map(function (i) { return i.json; });
if (rows.length < 100) { throw new Error('ABORT: INVESTORS returned only ' + rows.length + ' rows'); }

const out = [];
for (const e of EDITS) {
  const hits = rows.filter(function (r) { return s(r.investor) === e.investor; });
  if (hits.length !== 1) { throw new Error('ABORT: expected 1 INVESTORS row for ' + e.investor + ', found ' + hits.length); }
  const h = hits[0];
  if (s(h.do_not_contact).toLowerCase() === 'yes') { throw new Error('ABORT: ' + e.investor + ' is do_not_contact'); }
  const row = { investor: e.investor };
  let changed = 0;
  for (const k of ['contact_person', 'email', 'sector', 'stage', 'cheque_inr_cr']) {
    if (e[k] !== undefined && s(h[k]) !== e[k]) { row[k] = e[k]; changed++; }
  }
  if (changed > 0) { out.push({ json: row }); }
}
if (out.length === 0) { throw new Error('ABORT: nothing to change - already applied?'); }
if (out.length > 10) { throw new Error('ABORT: ' + out.length + ' exceeds guard of 10'); }
return out;
